import type { Metadata } from 'next'
import { AccesoForm } from '@/components/infraestructura/acceso-form'
import { ActualizacionForm } from '@/components/infraestructura/actualizacion-form'
import { EncabezadoParte, TITULO_PROGRAMA_COMPLETO } from '@/components/infraestructura/encabezado-parte'
import { tieneAccesoAlParteDesdeCookies } from '@/lib/infraestructura/acceso-parte'
import { resolverContextoPorCue, type ContextoErrorKind } from '@/lib/infraestructura/contexto'
import { ensureGeSchema, getCorteVigente, openGeDb } from '@/lib/infraestructura/ge-db'
import { destinoParaParte, enlaceDestino } from '@/lib/infraestructura/destino-carga'
import { obtenerParteActual } from '@/lib/infraestructura/parte-consulta'
import { redirect } from 'next/navigation'
import { ensureSeeded } from '@/lib/db/seed'
import { listarMotivos } from '@/lib/infraestructura/motivos'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export const metadata: Metadata = {
  title: `Actualizar · ${TITULO_PROGRAMA_COMPLETO}`,
}

const TITULO = 'Actualizar'

// Mismos textos que app/problematicas/parte/page.tsx y
// app/problematicas/parte/nuevo/page.tsx: el director no debería leer dos
// explicaciones distintas del mismo problema según por qué enlace entró.
const MENSAJES_ERROR: Record<ContextoErrorKind, string> = {
  cue_ausente: 'Este enlace no incluye el CUE de la escuela. Solicite el enlace nuevamente a quien se lo compartió.',
  cue_invalido: 'El CUE incluido en el enlace no tiene un formato válido.',
  sin_corte_vigente: 'No hay datos de escuelas disponibles en este momento. Intente nuevamente más tarde.',
  cue_inexistente: 'No se encontró una escuela con ese CUE.',
  sin_secciones: 'Esta escuela todavía no tiene secciones cargadas.',
}

/**
 * Pantalla "Actualizar el parte" (spec §8): el director modifica lo que
 * cambió en una situación ya en seguimiento. Misma guarda de acceso y
 * resolución de contexto que el resto del recorrido público (spec §6, §7):
 * sin la cookie de acceso, el director ve el formulario de ingreso; con
 * ella, la página resuelve el establecimiento y entrega el formulario de
 * actualización, que a su vez trae el estado vigente del parte por su
 * cuenta (mismo GET que EstadoActualParte).
 */
export default async function ActualizarPartePage({
  searchParams,
}: {
  searchParams: Promise<{ cue?: string }>
}) {
  const { cue } = await searchParams

  if (!(await tieneAccesoAlParteDesdeCookies())) {
    return (
      <div className="publico-content">
        <EncabezadoParte pantalla={TITULO} />
        <AccesoForm />
      </div>
    )
  }

  const clienteGe = openGeDb()
  let resultado
  // El corte se lee con el mismo cliente, antes de cerrarlo: la guarda de
  // abajo lo necesita y abrir una segunda conexión sólo para eso sería otra
  // ida a disco por cada carga de la pantalla.
  let corteId: number | null = null
  try {
    await ensureGeSchema(clienteGe)
    resultado = await resolverContextoPorCue(clienteGe, cue ?? null)
    corteId = (await getCorteVigente(clienteGe))?.id ?? null
  } finally {
    clienteGe.close()
  }

  if (!resultado.ok) {
    return (
      <div className="publico-content">
        <EncabezadoParte pantalla={TITULO} />
        <p className="estado-actual-aviso__texto" role="alert">
          {MENSAJES_ERROR[resultado.error.kind]}
        </p>
      </div>
    )
  }

  const { escuela, turnos } = resultado.contexto

  await ensureSeeded()

  // El director recibe un enlace y una contraseña, no un mapa del sitio: si
  // lo que le toca es la otra pantalla, se lo lleva sola. Las dos rutas
  // siguen existiendo, pero ninguna deja a nadie en el lugar equivocado.
  const destino = destinoParaParte(
    corteId === null ? null : await obtenerParteActual(escuela.cueAnexo, corteId),
  )
  if (destino !== 'actualizar') redirect(enlaceDestino(destino, escuela.cueAnexo))

  const motivos = await listarMotivos()

  return (
    <div className="publico-content publico-content--ancho">
      <EncabezadoParte
        pantalla={TITULO}
        escuela={escuela}
        descripcion="Revise lo informado hasta ahora y agregue o corrija lo que cambió."
      />
      <ActualizacionForm cue={escuela.cueAnexo} turnos={turnos} motivos={motivos} />
    </div>
  )
}

// @vitest-environment jsdom
import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import path from 'node:path'
import { eq } from 'drizzle-orm'
import { render, screen } from '@testing-library/react'
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest'
import { getDb } from '@/lib/db'
import { infraVerificacion } from '@/lib/db/schema'
import { ensureSeeded, PERIODO_ENOS_2026_2027_ID } from '@/lib/db/seed'
import { crearEpisodio } from '@/lib/infraestructura/episodios'
import { ensureGeSchema, openGeDb } from '@/lib/infraestructura/ge-db'
import { claveDePrueba } from '@/lib/infraestructura/claves-de-prueba'
import { crearVerificacion, responderPorEnlace } from '@/lib/infraestructura/verificaciones'

const CLAVE = claveDePrueba()

const cookiesGetMock = vi.fn()
vi.mock('next/headers', () => ({
  cookies: async () => ({ get: cookiesGetMock }),
}))
// Sin sesión: 'sin cookie de acceso' tiene que seguir mostrando el ingreso.
vi.mock('@/lib/session', () => ({ getSessionUser: async () => null }))
vi.mock('next/navigation', () => ({
  useRouter: () => ({ refresh: vi.fn() }),
}))

const { default: NuevoPartePage } = await import('./page')
const { crearTokenSesion } = await import('@/lib/infraestructura/acceso-publico')
const { NOMBRE_COOKIE_SESION_VERIFICACION, crearSesionVerificacion } = await import(
  '@/lib/infraestructura/verificacion-sesion'
)

let dir: string
let prevDataDir: string | undefined
let prevPassword: string | undefined

// Base Hub (getDb() cachea el cliente) y base GE comparten un único tmpdir
// para todo el archivo — mismo patrón que app/problematicas/parte/page.test.tsx.
// getDb() no se puede reapuntar entre tests, así que borrar el directorio por
// test dejaría el cliente apuntando a un archivo movido (SQLITE_READONLY_DBMOVED)
// en cuanto un caso necesite escribir una verificación.
beforeAll(async () => {
  dir = mkdtempSync(path.join(tmpdir(), 'parte-nuevo-page-'))
  prevDataDir = process.env.DATA_DIR
  prevPassword = process.env.PROBLEMATICAS_ACCESO_PASSWORD
  process.env.DATA_DIR = dir
  process.env.PROBLEMATICAS_ACCESO_PASSWORD = CLAVE
  await ensureSeeded()
})

afterAll(() => {
  if (prevDataDir === undefined) delete process.env.DATA_DIR
  else process.env.DATA_DIR = prevDataDir
  if (prevPassword === undefined) delete process.env.PROBLEMATICAS_ACCESO_PASSWORD
  else process.env.PROBLEMATICAS_ACCESO_PASSWORD = prevPassword
  rmSync(dir, { recursive: true, force: true })
})

beforeEach(() => {
  cookiesGetMock.mockReset()
  document.body.innerHTML = ''
})

function conAcceso() {
  const { token } = crearTokenSesion()
  cookiesGetMock.mockReturnValue({ value: token })
}

// La página sólo distingue la cookie de acceso público de la de sesión de
// verificación por su nombre, así que el mock devuelve la sesión acotada sólo
// cuando se la piden por ese nombre.
function conCookieDeSesionVerificacion(valorCookie: string) {
  cookiesGetMock.mockImplementation((nombre: string) =>
    nombre === NOMBRE_COOKIE_SESION_VERIFICACION ? { value: valorCookie } : undefined,
  )
}

// Verificación pendiente real + la cookie que emitiría el canje del token,
// mismo mecanismo que app/problematicas/parte/page.test.tsx. La hub vive en un
// tmpdir (ver beforeEach), por eso ensureSeeded() corre antes de tocar la base.
async function sesionDeVerificacionParaCue(cueAnexo: string) {
  await ensureSeeded()
  const episodio = await crearEpisodio({
    periodoId: PERIODO_ENOS_2026_2027_ID,
    nombre: 'Episodio de prueba',
  })
  const creada = await crearVerificacion({
    episodioId: episodio.id,
    cueAnexo,
    solicitadaPorUserId: 'user-director',
  })
  if (!creada.ok) throw new Error(`no se pudo crear la verificación: ${creada.motivo}`)
  const { valorCookie } = crearSesionVerificacion(creada.verificacion.id, cueAnexo)
  return { token: creada.token, verificacion: creada.verificacion, valorCookie }
}

async function seedEscuelaConSeccion() {
  const client = openGeDb()
  try {
    await ensureGeSchema(client)
    await client.execute(
      "INSERT OR IGNORE INTO ge_corte (id, ciclo_lectivo, fetched_at, estado) VALUES (1, 2026, '2026-03-01T00:00:00Z', 'vigente')",
    )
    await client.execute({
      sql: `INSERT INTO ge_localizacion (cue_anexo, cui, nombre, departamento, localidad)
            VALUES ('1801605-04', NULL, 'Escuela 4', 'Entre Rios', 'Parana')
            ON CONFLICT(cue_anexo) DO UPDATE SET nombre = excluded.nombre`,
      args: [],
    })
    await client.execute(
      "INSERT OR IGNORE INTO ge_seccion (corte_id, ge_section_id, cue_anexo, curso, division, nivel, turno) VALUES (1, 10, '1801605-04', '1', 'A', 'Primario', 'Mañana')",
    )
    await client.execute(
      'INSERT OR IGNORE INTO ge_alumno_seccion (corte_id, ge_section_id, ge_person_id) VALUES (1, 10, 900001)',
    )
  } finally {
    client.close()
  }
}

describe('NuevoPartePage', () => {
  it('sin cookie de acceso, muestra la pantalla de ingreso en vez del formulario', async () => {
    await seedEscuelaConSeccion()
    cookiesGetMock.mockReturnValue(undefined)

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '1801605-04' }) })
    render(jsx)

    expect(screen.getByLabelText(/contraseña/i)).toBeInTheDocument()
    expect(screen.queryByText('Escuela 4')).not.toBeInTheDocument()
  })

  it('con cookie de acceso vigente, encabeza con el programa y abre el asistente', async () => {
    await seedEscuelaConSeccion()
    conAcceso()

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '1801605-04' }) })
    render(jsx)

    // El título es el del programa; la escuela queda como identidad
    // subordinada, una sola vez y sin encabezar la pantalla.
    expect(
      screen.getByRole('heading', { level: 1, name: 'Registro de Incidencias ENOS 2026/2027' }),
    ).toBeInTheDocument()
    expect(screen.queryByRole('heading', { name: 'Escuela 4' })).toBeNull()
    expect(screen.getByText('Escuela 4')).toBeInTheDocument()

    expect(screen.getByText('Paso 1 de 4')).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: /agregar afectación/i })).toBeNull()
  })

  it('muestra un error claro sin CUE, sin ofrecer alternativas', async () => {
    await seedEscuelaConSeccion()
    conAcceso()

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({}) })
    render(jsx)

    expect(screen.getByText(/no incluye el CUE/i)).toBeInTheDocument()
    expect(screen.queryByText(/1801605/)).not.toBeInTheDocument()
  })

  it('muestra un error claro para un CUE inexistente', async () => {
    await seedEscuelaConSeccion()
    conAcceso()

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '9999999' }) })
    render(jsx)

    expect(screen.getByText(/no se encontró una escuela/i)).toBeInTheDocument()
  })
})

describe('NuevoPartePage — acceso por sesión de verificación', () => {
  it('sesión canjeada válida para el CUE de la query: renderiza el asistente, no el ingreso', async () => {
    const { valorCookie } = await sesionDeVerificacionParaCue('1801605-04')
    await seedEscuelaConSeccion()
    conCookieDeSesionVerificacion(valorCookie)

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '1801605-04' }) })
    render(jsx)

    expect(screen.queryByLabelText(/contraseña/i)).toBeNull()
    expect(screen.getByText('Paso 1 de 4')).toBeInTheDocument()
    expect(screen.getByText('Escuela 4')).toBeInTheDocument()
  })

  it('la misma sesión con OTRO CUE: no abre el CUE ajeno, muestra el ingreso', async () => {
    const { valorCookie } = await sesionDeVerificacionParaCue('1801605-04')
    conCookieDeSesionVerificacion(valorCookie)

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '1801605-99' }) })
    render(jsx)

    expect(screen.getByLabelText(/contraseña/i)).toBeInTheDocument()
  })

  it('sesión cuya verificación fue revocada: muestra el ingreso', async () => {
    const { valorCookie, verificacion } = await sesionDeVerificacionParaCue('1801605-04')
    await getDb()
      .update(infraVerificacion)
      .set({ tokenRevocadoEn: new Date().toISOString() })
      .where(eq(infraVerificacion.id, verificacion.id))
    conCookieDeSesionVerificacion(valorCookie)

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '1801605-04' }) })
    render(jsx)

    expect(screen.getByLabelText(/contraseña/i)).toBeInTheDocument()
    expect(screen.queryByText('Escuela 4')).toBeNull()
  })

  it('sesión cuya verificación ya fue respondida: muestra el ingreso', async () => {
    const { valorCookie, token, verificacion } = await sesionDeVerificacionParaCue('1801605-04')
    const respuesta = await responderPorEnlace({
      verificacionId: verificacion.id,
      token,
      resultado: 'sin_afectacion',
    })
    expect(respuesta.ok).toBe(true)
    conCookieDeSesionVerificacion(valorCookie)

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '1801605-04' }) })
    render(jsx)

    expect(screen.getByLabelText(/contraseña/i)).toBeInTheDocument()
    expect(screen.queryByText('Escuela 4')).toBeNull()
  })

  it('regresión: la contraseña compartida sigue abriendo el asistente', async () => {
    await seedEscuelaConSeccion()
    conAcceso()

    const jsx = await NuevoPartePage({ searchParams: Promise.resolve({ cue: '1801605-04' }) })
    render(jsx)

    expect(screen.queryByLabelText(/contraseña/i)).toBeNull()
    expect(screen.getByText('Paso 1 de 4')).toBeInTheDocument()
  })
})

import type { Metadata } from 'next'
import { AccesoForm } from '@/components/infraestructura/acceso-form'
import { EncabezadoParte, TITULO_PROGRAMA_COMPLETO } from '@/components/infraestructura/encabezado-parte'
import { ReporteInicialForm } from '@/components/infraestructura/reporte-inicial-form'
import {
  tieneAccesoAlParteDesdeCookies,
  tieneAccesoAlParteParaCueDesdeCookies,
} from '@/lib/infraestructura/acceso-parte'
import { resolverContextoPorCue, type ContextoErrorKind } from '@/lib/infraestructura/contexto'
import { ensureGeSchema, getCorteVigente, openGeDb } from '@/lib/infraestructura/ge-db'
import { destinoParaParte, enlaceDestino } from '@/lib/infraestructura/destino-carga'
import { obtenerParteActual } from '@/lib/infraestructura/parte-consulta'
import { redirect } from 'next/navigation'
import { ensureSeeded } from '@/lib/db/seed'
import { listarMotivos } from '@/lib/infraestructura/motivos'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export const metadata: Metadata = {
  title: `Iniciar un reporte · ${TITULO_PROGRAMA_COMPLETO}`,
}

const TITULO = 'Iniciar un reporte'

// Mismos textos que app/problematicas/parte/page.tsx: el director no debería
// leer dos explicaciones distintas del mismo problema según por qué enlace
// entró.
const MENSAJES_ERROR: Record<ContextoErrorKind, string> = {
  cue_ausente: 'Este enlace no incluye el CUE de la escuela. Solicite el enlace nuevamente a quien se lo compartió.',
  cue_invalido: 'El CUE incluido en el enlace no tiene un formato válido.',
  sin_corte_vigente: 'No hay datos de escuelas disponibles en este momento. Intente nuevamente más tarde.',
  cue_inexistente: 'No se encontró una escuela con ese CUE.',
  sin_secciones: 'Esta escuela todavía no tiene secciones cargadas.',
}

/**
 * Pantalla "Iniciar un reporte" (spec §7): primer paso del parte, donde el
 * director informa la actualización del estado de su establecimiento.
 *
 * Misma guarda de acceso y resolución de contexto que la pantalla del estado
 * actual (spec §6): sin la cookie de acceso, el director ve el formulario de
 * ingreso; con ella, la página resuelve el establecimiento y entrega el
 * formulario de reporte inicial (mismos motivos sembrados que el resto del
 * recorrido público).
 */
export default async function NuevoPartePage({
  searchParams,
}: {
  searchParams: Promise<{ cue?: string }>
}) {
  const { cue } = await searchParams

  const tieneAcceso = cue
    ? await tieneAccesoAlParteParaCueDesdeCookies(cue)
    : await tieneAccesoAlParteDesdeCookies()

  if (!tieneAcceso) {
    return (
      <div className="publico-content">
        <EncabezadoParte pantalla={TITULO} />
        <AccesoForm />
      </div>
    )
  }

  const clienteGe = openGeDb()
  let resultado
  // El corte se lee con el mismo cliente, antes de cerrarlo: la guarda de
  // abajo lo necesita y abrir una segunda conexión sólo para eso sería otra
  // ida a disco por cada carga de la pantalla.
  let corteId: number | null = null
  try {
    await ensureGeSchema(clienteGe)
    resultado = await resolverContextoPorCue(clienteGe, cue ?? null)
    corteId = (await getCorteVigente(clienteGe))?.id ?? null
  } finally {
    clienteGe.close()
  }

  if (!resultado.ok) {
    return (
      <div className="publico-content">
        <EncabezadoParte pantalla={TITULO} />
        <p className="estado-actual-aviso__texto" role="alert">
          {MENSAJES_ERROR[resultado.error.kind]}
        </p>
      </div>
    )
  }

  const { escuela, turnos } = resultado.contexto

  await ensureSeeded()

  // El director recibe un enlace y una contraseña, no un mapa del sitio: si
  // lo que le toca es la otra pantalla, se lo lleva sola. Las dos rutas
  // siguen existiendo, pero ninguna deja a nadie en el lugar equivocado.
  const destino = destinoParaParte(
    corteId === null ? null : await obtenerParteActual(escuela.cueAnexo, corteId),
  )
  if (destino !== 'nuevo') redirect(enlaceDestino(destino, escuela.cueAnexo))

  const motivos = await listarMotivos()

  return (
    <div className="publico-content">
      <EncabezadoParte
        pantalla={TITULO}
        escuela={escuela}
        descripcion="Informe un hecho. Le vamos a hacer unas pocas preguntas, de a una por vez."
      />
      <ReporteInicialForm cue={escuela.cueAnexo} turnos={turnos} motivos={motivos} />
    </div>
  )
}

import { cookies } from 'next/headers'
import { getSessionUser } from '@/lib/session'
import {
  NOMBRE_COOKIE,
  tieneAccesoPublico,
  tieneAccesoPublicoDesdeValorCookie,
} from '@/lib/infraestructura/acceso-publico'
import {
  extraerCookieVerificacionSesion,
  NOMBRE_COOKIE_SESION_VERIFICACION,
  verificacionIdDeSesionValida,
} from '@/lib/infraestructura/verificacion-sesion'
import { verificacionHabilitaSesionEscritura } from '@/lib/infraestructura/verificaciones'

/*
  Guarda del recorrido del parte: contraseña pública O sesión de administrador.

  Por qué existe este módulo y no un cambio dentro de acceso-publico.ts: ese
  archivo se declara la única costura con el mundo público y promete que el día
  que llegue la autenticación por token se reescribe él solo, sin tocar a sus
  llamadores. Meterle la sesión del hub adentro rompería esa promesa —pasaría a
  depender de la base y del rol—, así que la composición vive acá, una capa
  arriba, y él sigue siendo sólo contraseña.

  El rol es 'admin' y no isStaff(): la contraseña se puso porque el contexto del
  parte incluye identidad de alumnos, y ese mismo dato ya tiene una regla de
  acceso escrita en permiso-nominal.ts, donde 'admin' entra sin grant y 'editor'
  queda afuera a propósito. Abrirle la puerta a 'editor' acá contradiría esa
  decisión por la ventana de al lado.

  El orden importa: primero la contraseña, que es una verificación HMAC en
  memoria, y sólo si falla se resuelve la sesión, que consulta la base. Así el
  director —que es quien más entra— nunca paga ese viaje.
*/

async function esAdministrador(): Promise<boolean> {
  const user = await getSessionUser()
  return Boolean(user && !user.banned && user.role === 'admin')
}

/** Para Route Handlers, que reciben la cookie dentro del Request. */
export async function tieneAccesoAlParte(request: Request): Promise<boolean> {
  if (tieneAccesoPublico(request)) return true
  return esAdministrador()
}

/** Para páginas del App Router, que leen la cookie del store de la request. */
export async function tieneAccesoAlParteDesdeCookies(): Promise<boolean> {
  const cookieStore = await cookies()
  if (tieneAccesoPublicoDesdeValorCookie(cookieStore.get(NOMBRE_COOKIE)?.value)) return true
  return esAdministrador()
}

/**
 * Acceso acotado al CUE exacto de una verificación (batch E1): un director
 * que entró por el enlace de "Hay afectación" puede usar el formulario de
 * parte SIN la contraseña compartida, pero SÓLO para ese CUE y sólo mientras
 * la sesión canjeada del token no venció. Nunca amplía a otro CUE ni a rol
 * admin — ver verificacion-sesion.ts para el alcance exacto.
 */
export async function tieneAccesoAlParteParaCue(request: Request, cueAnexo: string): Promise<boolean> {
  if (await tieneAccesoAlParte(request)) return true
  const cookieHeader = request.headers.get('cookie')
  const valor = extraerCookieVerificacionSesion(cookieHeader)
  const verificacionId = verificacionIdDeSesionValida(valor, cueAnexo)
  if (!verificacionId) return false
  return verificacionHabilitaSesionEscritura(verificacionId)
}

/** Para Server Components (app/problematicas/parte/page.tsx). */
export async function tieneAccesoAlParteParaCueDesdeCookies(cueAnexo: string): Promise<boolean> {
  if (await tieneAccesoAlParteDesdeCookies()) return true
  const cookieStore = await cookies()
  const valor = cookieStore.get(NOMBRE_COOKIE_SESION_VERIFICACION)?.value
  const verificacionId = verificacionIdDeSesionValida(valor, cueAnexo)
  if (!verificacionId) return false
  return verificacionHabilitaSesionEscritura(verificacionId)
}

// A qué pantalla de carga corresponde mandar al director: la del primer
// reporte o la de actualización.
//
// El director recibe un enlace y una contraseña, no un mapa del sitio. No
// tiene por qué saber si lo que le toca es "iniciar" o "actualizar" — eso
// depende del estado del parte, que es justamente lo que viene a consultar.
// Las dos rutas siguen existiendo (el estado actual enlaza a la que
// corresponde), pero cada una se corrige sola si le llega alguien al lugar
// equivocado.
//
// La regla es la misma que sinSituacionEnSeguimiento en
// estado-actual-textos.ts, para que la redirección y el mensaje de §17 nunca
// discrepen: sin período, sin parte o sin ninguna afectación vigente, no hay
// nada que actualizar.
import type { ParteActual } from '@/lib/infraestructura/parte-consulta'
import { snapshotDesde } from '@/lib/infraestructura/parte-consulta'

export type DestinoCarga = 'nuevo' | 'actualizar'

export const RUTA_DESTINO: Record<DestinoCarga, string> = {
  nuevo: '/problematicas/parte/nuevo',
  actualizar: '/problematicas/parte/actualizar',
}

/**
 * Decisión pura, para poder probarla sin base: `null` es "no hay período
 * vigente", que se trata igual que "todavía no hay nada informado".
 */
export function destinoParaParte(actual: ParteActual | null): DestinoCarga {
  if (!actual || !actual.parte) return 'nuevo'
  return snapshotDesde(actual).afectaciones.length > 0 ? 'actualizar' : 'nuevo'
}

/** URL de la pantalla que corresponde, conservando el CUE del enlace. */
export function enlaceDestino(destino: DestinoCarga, cueAnexo: string): string {
  return `${RUTA_DESTINO[destino]}?cue=${encodeURIComponent(cueAnexo)}`
}

